void UControlRig::InitializeFromCDO()
{
	// Flag the rig as needing sequencer re-initialization. Scoped to Runtime Asset-backed
	// rigs because they re-initialize the same UObject in place (same GetUniqueID()), so
	// sequencer's HasControlRigTrack(UniqueID) check would otherwise skip the refresh.
	// BP rigs get a new UObject via FBlueprintCompileReinstancer, so they don't need this.
	if (!HasAnyFlags(RF_ClassDefaultObject) && GetGeneratedByAsset().GetObject() != nullptr)
	{
		bNeedsInstanceInitialization = true;
	}

	InitializeVMsFromCDO();

	DECLARE_SCOPE_HIERARCHICAL_COUNTER_FUNC()

	// copy CDO property you need to here
	if (!HasAnyFlags(RF_ClassDefaultObject))
	{
		if (!IsRigModuleInstance())
		{
			// similar to FControlRigBlueprintCompilerContext::CopyTermDefaultsToDefaultObject,
			// where CDO is initialized from BP there,
			// we initialize all other instances of Control Rig from the CDO here
			URigHierarchy* DefaultHierarchy = nullptr;
			FRigHierarchySettings* DefaultHierarchySettings = nullptr;
			FRigElementKeyRedirector* DefaultElementKeyRedirector = nullptr;
			FRigModuleSettings* DefaultRigModuleSettings = nullptr;
			if (TScriptInterface<IControlRigRuntimeAssetInterface> RuntimeAsset = GeneratedBy.GetObject())
			{
				DefaultHierarchy = RuntimeAsset->GetHierarchy();
				DefaultHierarchySettings = &RuntimeAsset->GetHierarchySettings();
				DefaultElementKeyRedirector = &RuntimeAsset->GetElementKeyRedirector();
				DefaultRigModuleSettings = &RuntimeAsset->GetRigModuleSettings();
			}
			else if (UControlRig* CDO = GetClass()->GetDefaultObject<UControlRig>())
			{
				DefaultHierarchy = CDO->GetHierarchy();
				DefaultHierarchySettings = &CDO->HierarchySettings;
				DefaultElementKeyRedirector = &CDO->ElementKeyRedirector;
				DefaultRigModuleSettings = &CDO->RigModuleSettings;
			}
			URigHierarchy* Hierarchy = GetHierarchy();

			// copy hierarchy
			{
				FRigHierarchyValidityBracket ValidityBracketA(Hierarchy);
				FRigHierarchyValidityBracket ValidityBracketB(DefaultHierarchy);

				TGuardValue<bool> Guard(Hierarchy->GetSuspendNotificationsFlag(), true);
				Hierarchy->CopyHierarchy(DefaultHierarchy);
				Hierarchy->ResetPoseToInitial(ERigElementType::All);
				bHierarchyInitializedThisFrame = true;

	}

	if(UpdateControlRigIfNeeded(InAnimInstance, InAnimInstance->GetRequiredBones()))
	{
		ControlRigHierarchyMappings.UpdateControlRigRefPoseIfNeeded(ControlRig
			, InProxy->GetAnimInstanceObject()
			, InProxy->GetSkelMeshComponent()
			, InProxy->GetRequiredBones()
			, bSetRefPoseFromSkeleton
			, /*bIncludePoseInHash*/ false);
	}

	FAnimNode_ControlRigBase::OnInitializeAnimInstance(InProxy, InAnimInstance);

	InitializeProperties(InAnimInstance, GetTargetAssetReference());
}

	}
}

void FControlRigHierarchyMappings::UpdateControlRigRefPoseIfNeeded(UControlRig* ControlRig
	, const UObject* InstanceObject
	, const USkeletalMeshComponent* SkeletalMeshComponent
	, const FBoneContainer& RequiredBones
	, bool bInSetRefPoseFromSkeleton
	, bool bIncludePoseInHash)
{
	check(ControlRig);

	if (!bInSetRefPoseFromSkeleton)
	{
		return;
	}

	int32 ExpectedHash = 0;
	ExpectedHash = HashCombine(ExpectedHash, (int32)reinterpret_cast<uintptr_t>(InstanceObject));

TransformB.SetLocation(Hierarchy->GetGlobalTransform(CachedItemBIndex).GetLocation());
FTransform TransformC = Effector;

float LengthA = ItemALength;
float LengthB = ItemBLength;

if (LengthA < SMALL_NUMBER)
{
	FTransform InitialTransformA = Hierarchy->GetInitialGlobalTransform(CachedItemAIndex);
	FVector Scale = FVector::OneVector;
	if (InitialTransformA.GetScale3D().SizeSquared() > SMALL_NUMBER)
	{
		Scale = TransformA.GetScale3D() / InitialTransformA.GetScale3D();
	}
	FVector Diff = InitialTransformA.GetLocation() - Hierarchy->GetInitialGlobalTransform(CachedItemBIndex).GetLocation();
	Diff = Diff * Scale;
	LengthA = Diff.Size();
}

if (LengthB < SMALL_NUMBER && CachedEffectorItemIndex != INDEX_NONE)
{
	FTransform InitialTransformB = Hierarchy->GetInitialGlobalTransform(CachedItemBIndex);
	FVector Scale = FVector::OneVector;
	if (InitialTransformB.GetScale3D().SizeSquared() > SMALL_NUMBER)
	{
		Scale = TransformB.GetScale3D() / InitialTransformB.GetScale3D();
	}
	FVector Diff = InitialTransformB.GetLocation() - Hierarchy->GetInitialGlobalTransform(CachedEffectorItemIndex).GetLocation();
	Diff = Diff * Scale;
	LengthB = Diff.Size();
}

void FAlsRigUnit_ApplyFootOffsetRotation::Initialize()
{
	bInitialized = false;
}

FAlsRigUnit_ApplyFootOffsetRotation_Execute()
{
	DECLARE_SCOPE_HIERARCHICAL_COUNTER_RIGUNIT()

	const auto* Hierarchy{ExecuteContext.Hierarchy};

	if (!IsValid(Hierarchy) ||
	    !CachedCalfItem.UpdateCache(CalfItem, Hierarchy) ||
	    !CachedFootItem.UpdateCache(FootItem, Hierarchy))
	{
		return;
	}

	if (!bInitialized)
	{
		bInitialized = true;

		OffsetNormal = FootOffsetNormal;

		// Get the foot initial rotation and convert it to the calf space.

		const auto CalfInitialRotation{Hierarchy->GetInitialGlobalTransform(CachedCalfItem).GetRotation()};
		const auto FootInitialRotation{Hierarchy->GetInitialGlobalTransform(CachedFootItem).GetRotation()};

		FootInitialRotationCalfSpace = CalfInitialRotation.Inverse() * FootInitialRotation;
	}
